import sys

MOD = 998244353

def main():
    input = sys.stdin.readline
    N, M = map(int, input().split())
    S = input().strip()

    size = 1 << N

    # popcount for masks up to 2^N
    pc = [0] * size
    for mask in range(1, size):
        pc[mask] = pc[mask >> 1] + (mask & 1)

    def get_f(mask):
        # f[i] = LCS(S[:i], current string), encoded by mask
        # bit j of mask means f[j+1] - f[j] == 1
        f = [0] * (N + 1)
        for i in range(1, N + 1):
            f[i] = pc[mask & ((1 << i) - 1)]
        return f

    trans = [[0] * 26 for _ in range(size)]

    for mask in range(size):
        f = get_f(mask)
        for ch in range(26):
            c = chr(ord('a') + ch)
            g = [0] * (N + 1)
            for i in range(1, N + 1):
                if S[i - 1] == c:
                    g[i] = max(g[i - 1], f[i - 1] + 1)
                else:
                    g[i] = max(g[i - 1], f[i])
            nmask = 0
            for i in range(1, N + 1):
                if g[i] != g[i - 1]:
                    nmask |= 1 << (i - 1)
            trans[mask][ch] = nmask

    dp = [0] * size
    dp[0] = 1

    for _ in range(M):
        ndp = [0] * size
        for mask, val in enumerate(dp):
            if val:
                for ch in range(26):
                    nmask = trans[mask][ch]
                    ndp[nmask] = (ndp[nmask] + val) % MOD
        dp = ndp

    ans = [0] * (N + 1)
    for mask, val in enumerate(dp):
        k = pc[mask]
        ans[k] = (ans[k] + val) % MOD

    print(*ans)

if __name__ == "__main__":
