    queries = sorted((X, R, idx) for idx, (R, X) in enumerate(
        map(lambda line: tuple(map(int, line.split())), [input() for _ in range(Q)])
    ))

    bit = [0] * (N + 2)

    def update(i, val):
        while i <= N:
            if bit[i] < val:
                bit[i] = val
            i += i & -i

    def query(i):
        res = 0
        while i > 0:
            if bit[i] > res:
                res = bit[i]
            i -= i & -i
        return res

    ans = [0] * Q
    p = 0

    for X, R, qi in queries:
        while p < N and points[p][0] <= X:
            group_start = p
            while p < N and points[p][0] == points[group_start][0]:
                p += 1

            updates = []
            for j in range(group_start, p):
                _, idx = points[j]
                val = query(idx - 1) + 1
                updates.append((idx, val))

            for idx, val in updates:
                update(idx, val)

        ans[qi] = query(R)

