def main():
    input = sys.stdin.readline
    N = int(input())
    C = [input().strip() for _ in range(N)]

    INF = 10**18
    dist = [[INF] * N for _ in range(N)]
    q = deque()

    for i in range(N):
        dist[i][i] = 0
        q.append((i, i))

    for i in range(N):
        for j in range(N):
            if C[i][j] != '-':
                if dist[i][j] > 1:
                    dist[i][j] = 1
                    q.append((i, j))

    # incoming[label][v] = bitset of u such that u -> v has this label
    incoming = [[0] * N for _ in range(26)]
    for i in range(N):
        for j in range(N):
            ch = C[i][j]
            if ch != '-':
                incoming[ord(ch) - 97][j] |= 1 << i

    while q:
        v, u = q.popleft()
        d = dist[v][u]

        for c in range(26):
            in_v = incoming[c][v]
            if in_v == 0:
                continue

            row = u
            x = in_v
            while x:
                lsb = x & -x
                x ^= lsb
                i = lsb.bit_length() - 1

                if C[row][i] == chr(97 + c):
                    if dist[i][u] > d + 1:
                        dist[i][u] = d + 1
                        q.append((i, u))

    for i in range(N):
        ans = []
        for j in range(N):
            ans.append(str(dist[i][j] if dist[i][j] != INF else -1))
        print(' '.join(ans))

