import sys

def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    it = iter(data)
    T = next(it)
    out = []

    for _ in range(T):
        N = next(it)
        A = [next(it) for _ in range(2 * N)]

        first = [-1] * (N + 1)
        last = [-1] * (N + 1)

        for i, x in enumerate(A):
            if first[x] == -1:
                first[x] = i
            else:
                last[x] = i

        adj = [False] * (N + 1)
        for x in range(1, N + 1):
            if last[x] == first[x] + 1:
                adj[x] = True

        cnt = {}
        for i in range(2 * N - 1):
            x, y = A[i], A[i + 1]
            if x == y:
                continue
            if adj[x] or adj[y]:
                continue
            if x < y:
                key = (x, y)
            else:
                key = (y, x)
            cnt[key] = cnt.get(key, 0) + 1

        ans = 0
        for v in cnt.values():
            ans += v * (v - 1) // 2

        out.append(str(ans))

    sys.stdout.write("\n".join(out))

