from collections import Counter

def possible(S: int, ca: Counter, cb: Counter, p: int, q: int, a: int, b: int) -> bool:
    if ca and max(ca) > S:
        return False
    if cb and max(cb) > S:
        return False

    ua = 0
    for x, cnt in ca.items():
        ua += max(0, cnt - cb.get(S - x, 0))
    if ua > b:
        return False

    ub = 0
    for y, cnt in cb.items():
        ub += max(0, cnt - ca.get(S - y, 0))
        if ub > a:
            return False

    return True

def main() -> None:
