    cb = Counter()
    a = b = 0

    max_fixed = 0

    for x in A:
        if x == -1:
            a += 1
        else:
            ca[x] += 1
            if x > max_fixed:
                max_fixed = x

    for y in B:
        if y == -1:
            b += 1
        else:
            cb[y] += 1
            if y > max_fixed:
                max_fixed = y

    p = sum(ca.values())
    q = sum(cb.values())

