    def minCost(self, n: int, cost: List[List[int]]) -> int:
        m = n // 2

        # State: (left_color, right_color), where colors are 0, 1, 2
        # and left_color != right_color.
        states = [(i, j) for i in range(3) for j in range(3) if i != j]

        # dp[state_index] = minimum cost up to current pair/column
        dp = [
            cost[0][a] + cost[n - 1][b]
            for a, b in states
        ]

        for k in range(1, m):
            left_idx = k
            right_idx = n - 1 - k

            new_dp = [float("inf")] * len(states)

            for idx, (a, b) in enumerate(states):
                current_cost = cost[left_idx][a] + cost[right_idx][b]

                for prev_idx, (pa, pb) in enumerate(states):
                    if pa != a and pb != b:
                        new_dp[idx] = min(new_dp[idx], dp[prev_idx] + current_cost)

            dp = new_dp

