    def countMentions(self, numberOfUsers: int, events: List[List[str]]) -> List[int]:
        mentions = [0] * numberOfUsers
        offline_until = [-1] * numberOfUsers

        events.sort(key=lambda e: (int(e[1]), 0 if e[0] == "OFFLINE" else 1))

        for event in events:
            timestamp = int(event[1])

            if event[0] == "OFFLINE":
                user_id = int(event[2])
                offline_until[user_id] = timestamp + 60
            else:
                mentions_string = event[2]

                if mentions_string == "ALL":
                    for user_id in range(numberOfUsers):
                        mentions[user_id] += 1
                elif mentions_string == "HERE":
                    for user_id in range(numberOfUsers):
                        if offline_until[user_id] <= timestamp:
                            mentions[user_id] += 1
                else:
                    for token in mentions_string.split():
                        user_id = int(token[2:])
                        mentions[user_id] += 1

        return mentions
