import heapq

class Solution:
    def findMaxSum(self, nums1: List[int], nums2: List[int], k: int) -> List[int]:
        n = len(nums1)
        if k == 0:
            return [0] * n

        indexed = sorted(zip(nums1, nums2, range(n)), key=lambda x: x[0])

        ans = [0] * n
        max_k_heap = []
        total = 0

        i = 0
        while i < n:
            current_value = indexed[i][0]
            j = i

            while j < n and indexed[j][0] == current_value:
                j += 1

            for t in range(i, j):
                ans[indexed[t][2]] = total

            for t in range(i, j):
                value = indexed[t][1]

                if len(max_k_heap) < k:
                    heapq.heappush(max_k_heap, value)
                    total += value
                elif value > max_k_heap[0]:
                    total += value - heapq.heapreplace(max_k_heap, value)

            i = j

        return ans
