class Solution:
    def minZeroArray(self, nums: List[int], queries: List[List[int]]) -> int:
        n = len(nums)

        def can_make_zero(k: int) -> bool:
            for i, target in enumerate(nums):
                if target == 0:
                    continue

                bits = 1

                for l, r, val in queries[:k]:
                    if l <= i <= r:
                        bits |= bits << val
                        if (bits >> target) & 1:
                            break

                if not ((bits >> target) & 1):
                    return False

            return True

        if not can_make_zero(len(queries)):
            return -1

        left, right = 0, len(queries)
        while left < right:
            mid = (left + right) // 2
            if can_make_zero(mid):
                right = mid
            else:
                left = mid + 1

