class Solution:
    def numberOfComponents(self, properties: List[List[int]], k: int) -> int:
        n = len(properties)
        parent = list(range(n))
        rank = [0] * n

        def find(x: int) -> int:
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        def union(a: int, b: int) -> None:
            ra, rb = find(a), find(b)
            if ra == rb:
                return

            if rank[ra] < rank[rb]:
                ra, rb = rb, ra

            parent[rb] = ra
            if rank[ra] == rank[rb]:
                rank[ra] += 1

        sets = [set(row) for row in properties]

        for i in range(n):
            for j in range(i + 1, n):
                if len(sets[i] & sets[j]) >= k:
                    union(i, j)

        return sum(1 for i in range(n) if find(i) == i)
