class Solution:
    def maxProduct(self, nums: List[int], k: int, limit: int) -> int:
        max_abs_sum = 12 * len(nums)
        if abs(k) > max_abs_sum:
            return -1

        width = 2 * max_abs_sum + 1
        offset = max_abs_sum
        mask = (1 << width) - 1

        # dp[p][parity] is a bitset of reachable alternating sums + offset
        # for a non-empty subsequence with product p and length parity.
        dp = [[0, 0] for _ in range(limit + 1)]

        for x in nums:
            new_dp = [row[:] for row in dp]

            if x == 0:
                new_dp[0][0] |= 1 << offset
                for p in range(1, limit + 1):
                    if dp[p][0]:
                        new_dp[0][1] |= 1 << offset
                    if dp[p][1]:
                        new_dp[0][0] |= 1 << offset
            else:
                # Append x to a non-empty subsequence.
                if x == 1:
                    for p in range(1, limit + 1):
                        bits = dp[p]
                        if bits[0]:
                            new_dp[p][1] |= ((bits[0] << x) & mask)
                        if bits[1]:
                            new_dp[p][0] |= ((bits[1] >> x) & mask)
                else:
                    for p in range(1, limit // x + 1):
                        q = p * x
                        bits = dp[p]
                        if bits[0]:
                            new_dp[q][1] |= ((bits[0] << x) & mask)
                        if bits[1]:
                            new_dp[q][0] |= ((bits[1] >> x) & mask)

                # Start a new subsequence consisting of just x.
                new_dp[x][1] |= 1 << (offset + x)

            dp = new_dp

        bit_pos = offset + k

        for p in range(limit, 0, -1):
            if (dp[p][0] | dp[p][1]) & (1 << bit_pos):
                return p

        if dp[0][0] | dp[0][1]:
            if (dp[0][0] | dp[0][1]) & (1 << bit_pos):
                return 0

        return -1
