            mid = (lo + hi) / 2.0
            below = 0.0

            for _, y, length in squares:
                if mid >= y + length:
                    below += length * length
                elif mid > y:
                    below += length * (mid - y)

            if below < target:
                lo = mid
            else:
                hi = mid

