class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        INF = 10**18

        odd_count = (n + 1) // 2
        even_count = n // 2

        fact = [1] * (n + 1)
        for i in range(1, n + 1):
            fact[i] = min(INF, fact[i - 1] * i)

        def count_completions(odd_left: int, even_left: int, next_odd: bool) -> int:
            remaining = odd_left + even_left
            if remaining == 0:
                return 1

            if next_odd:
                odd_needed = (remaining + 1) // 2
                even_needed = remaining // 2
            else:
                odd_needed = remaining // 2
                even_needed = (remaining + 1) // 2

            if odd_left != odd_needed or even_left != even_needed:
                return 0

            return min(INF, fact[odd_left] * fact[even_left])

        if n % 2 == 0:
            total = min(INF, 2 * fact[odd_count] * fact[even_count])
        else:
            total = min(INF, fact[odd_count] * fact[even_count])

        if k > total:
            return []

        used = [False] * (n + 1)
        ans = []
        odd_left = odd_count
        even_left = even_count
        next_odd = None

        for _ in range(n):
            chosen = -1

            for num in range(1, n + 1):
                if used[num]:
                    continue

                is_odd = num % 2 == 1

                if next_odd is not None and is_odd != next_odd:
                    continue

                if is_odd:
                    odd_left -= 1
                else:
                    even_left -= 1

                ways = count_completions(odd_left, even_left, not is_odd)

                if k > ways:
                    k -= ways
                    if is_odd:
                        odd_left += 1
                    else:
                        even_left += 1
                else:
                    chosen = num
                    break

            if chosen == -1:
                return []

            used[chosen] = True
            ans.append(chosen)
            next_odd = not (chosen % 2 == 1)

        return ans
